import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.DMXcdKmJ.js";const l=JSON.parse('{"title":"接入 WebSocket 并映射消息","description":"保存 WebSocket 会话、运行短时消息预览、配置输出映射，并核对真实消息与正式运行。","frontmatter":{"title":"接入 WebSocket 并映射消息","description":"保存 WebSocket 会话、运行短时消息预览、配置输出映射，并核对真实消息与正式运行。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/websocket-outputs.md","filePath":"zh/使用指南/接入WebSocket并映射消息.md"}'),i={name:"zh/guide/websocket-outputs.md"};function s(d,e,n,c,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="接入-websocket-并映射消息" tabindex="-1">接入 WebSocket 并映射消息 <a class="header-anchor" href="#接入-websocket-并映射消息" aria-label="Permalink to &quot;接入 WebSocket 并映射消息&quot;">​</a></h1><p>入口：<strong>数据中心 → 接入源 → 新建连接 → WebSocket</strong>。先准备服务地址、认证、子协议及消息约定，确认平台环境能访问服务。</p><p>会话连接或发送消息都可能影响外部服务，应先获准。不要把任意生产控制消息作为测试内容。</p><h2 id="_1-保存会话" tabindex="-1">1. 保存会话 <a class="header-anchor" href="#_1-保存会话" aria-label="Permalink to &quot;1. 保存会话&quot;">​</a></h2><p>创建接入源并打开工作台，点击 <strong>“新建会话”</strong>。填写名称、地址以及实际需要的认证、请求头或子协议，再点击 <strong>“保存”</strong>。</p><p>AI 已创建时，在此接入源按会话名称查找。仅有页面里的 WebSocket 代码，不等于这里已保存平台会话。</p><h2 id="_2-运行预览" tabindex="-1">2. 运行预览 <a class="header-anchor" href="#_2-运行预览" aria-label="Permalink to &quot;2. 运行预览&quot;">​</a></h2><p>使用 **“运行预览”**查看连接与消息流；服务需要发送约定消息时，在“消息”区域准备内容，按 **“保存并预览”**验证。</p><p>先核对实际接收或发送方向、内容、时间和错误。不要把成功握手当成业务订阅成功，也不要把上次显示的消息当成当前还在接收。</p><p>预览是一次受限制的开发检查，不是要求用户一直开着窗口充当正式采集进程。</p><h2 id="_3-配置输出映射" tabindex="-1">3. 配置输出映射 <a class="header-anchor" href="#_3-配置输出映射" aria-label="Permalink to &quot;3. 配置输出映射&quot;">​</a></h2><p>在 **“输出映射”**根据实际消息设置完整消息或所需字段的输出，明确类型和取值路径，再保存。</p><p>到“数据点”核对真实路径、来源与值。消息内容是对象或数组时，先确定计算、报警需要哪个字段；没有新消息或消息格式变化时，检查质量和时间，不填一个正常默认值掩盖故障。</p><h2 id="_4-结束和继续使用" tabindex="-1">4. 结束和继续使用 <a class="header-anchor" href="#_4-结束和继续使用" aria-label="Permalink to &quot;4. 结束和继续使用&quot;">​</a></h2><p>使用“取消预览”结束当前检查，核对结果。关闭或清空消息显示不等于清理服务端业务状态。</p><p>正式使用还需核对部署内容、运行支持、断线恢复及实际消息链路。界面可以配置和保存，不意味着所有服务的子协议和重连场景都已经通过验证。</p><p>下一步：<a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a> · <a href="/induframe-docs/zh/guide/datapoints.html">数据点列表</a> · <a href="/induframe-docs/zh/guide/data-flow-tutorial.html">计算与报警联动</a>。</p>',17)])])}const u=a(i,[["render",s]]);export{l as __pageData,u as default};
